"""Sound effects for PylonChess.

All effect samples are synthesised in memory (no audio files needed) and played
through pygame.mixer. If the audio device cannot be initialised the manager
silently disables itself.
"""

import io
import math
import struct

import pygame


def _wav_bytes(sample_rate, samples, channels=1):
    """Encode a list of float samples in [-1, 1] as a small 16-bit WAV.
    With `channels == 2` the same sample is sent to both speakers."""
    data = bytearray()
    for s in samples:
        v = int(max(-1.0, min(1.0, s)) * 32767)
        if channels == 2:
            data += struct.pack("<hh", v, v)
        else:
            data += struct.pack("<h", v)
    # 44-byte WAV header
    n = len(data)
    block = channels * 2
    header = (
        b"RIFF" + struct.pack("<I", 36 + n) + b"WAVE" +
        b"fmt " + struct.pack("<I", 16) + struct.pack("<HHIIHH", 1, channels,
                                                      sample_rate,
                                                      sample_rate * block,
                                                      block, 16) +
        b"data" + struct.pack("<I", n)
    )
    return header + bytes(data)


def _tone(sample_rate, freq, duration, attack=0.005, decay=0.4, harmonics=()):
    """A short plucked/click tone with an exponential decay envelope.
    `harmonics` is a list of (multiplier, amplitude) pairs."""
    count = int(sample_rate * duration)
    samples = []
    for i in range(count):
        t = i / sample_rate
        env = math.exp(-t * decay) * min(1.0, t / max(attack, 1e-6))
        s = math.sin(2 * math.pi * freq * t)
        s += sum(amp * math.sin(2 * math.pi * freq * mult * t) for mult, amp in harmonics)
        samples.append(env * s / (1 + len(harmonics)))
    return samples


class SoundManager:
    """Lazy synthesised sound effects with an on/off switch."""

    def __init__(self, enabled=True):
        self.enabled = enabled
        self.mixer_ok = False
        self._sounds = {}
        self._rate = 22050
        self._channels = 1
        # Any audio trouble must never block startup or crash the game. We ask
        # for the mixer's standard default format first; an unusual mono/22050
        # device can be rejected by some sound hardware with "invalid argument".
        try:
            pygame.init()
            if not pygame.mixer.get_init():
                try:
                    pygame.mixer.init()
                except pygame.error:
                    try:
                        pygame.mixer.init(self._rate, -16, 1, 256)
                    except pygame.error:
                        pass
            self.mixer_ok = pygame.mixer.get_init() is not None
        except Exception:
            self.mixer_ok = False
        if self.mixer_ok:
            self._match_mixer_format()
            try:
                self._build_sounds()
            except Exception:
                self._sounds = {}
                self.mixer_ok = False

    def _match_mixer_format(self):
        """Store the mixer's actual rate/channels so buffers are built in a
        format SDL accepts without conversion."""
        try:
            info = pygame.mixer.get_init()
            if info:
                self._rate = info[0]
                self._channels = 1 if info[2] is None else info[2]
        except Exception:
            pass

    def _build_sounds(self):
        rate = self._rate
        self._sounds["move"] = self._make(_tone(rate, 520, 0.09, decay=18.0))
        self._sounds["capture"] = self._make(_tone(rate, 300, 0.14, decay=12.0, harmonics=((2, 0.5), (3, 0.25))))
        self._sounds["check"] = self._make(_tone(rate, 880, 0.16, decay=10.0, harmonics=((2, 0.6),)))
        self._sounds["castle"] = self._make(_tone(rate, 400, 0.18, decay=11.0) + _tone(rate, 600, 0.12, decay=14.0))
        self._sounds["promote"] = self._make(_tone(rate, 660, 0.10, decay=14.0) + _tone(rate, 990, 0.18, decay=10.0))
        self._sounds["game_over"] = self._make(
            _tone(rate, 440, 0.15, decay=8.0) + _tone(rate, 330, 0.2, decay=7.0) +
            _tone(rate, 220, 0.3, decay=6.0))
        self._sounds["hint"] = self._make(_tone(rate, 1200, 0.07, decay=20.0) + _tone(rate, 1600, 0.08, decay=18.0))

    def _make(self, samples):
        buff = _wav_bytes(self._rate, samples, self._channels)
        return pygame.mixer.Sound(buffer=buff)

    def toggle(self):
        self.enabled = not self.enabled
        return self.enabled

    def set_enabled(self, enabled):
        self.enabled = enabled

    def play(self, name):
        if not self.enabled or not self.mixer_ok:
            return
        sound = self._sounds.get(name)
        if sound and self.mixer_ok:
            try:
                sound.play()
            except Exception:
                pass